import {redirect} from 'next/navigation';import {createClient} from '@/lib/supabase/server';
async function login(formData:FormData){'use server';const db=await createClient();const{data,error}=await db.auth.signInWithPassword({email:String(formData.get('email')??''),password:String(formData.get('password')??'')});if(error||!data.user)redirect('/vendor/login?error=identifiants');const{data:membership}=await db.from('restaurant_members').select('restaurant_id').eq('user_id',data.user.id).limit(1);if(!membership?.length){await db.auth.signOut();redirect('/vendor/login?error=acces')}redirect('/')}
export default async function VendorLogin({searchParams}:{searchParams:Promise<{error?:string}>}){const{error}=await searchParams;return <main className="auth-page"><section className="auth-card"><p className="section-kicker">Espace restaurant</p><h1>Connexion vendeur</h1><p>Accédez aux données du restaurant qui vous a été attribué.</p>{error?<div className="notice">Accès vendeur non reconnu.</div>:null}<form action={login}><label className="field"><span>Email</span><input name="email" type="email" required/></label><label className="field"><span>Mot de passe</span><input name="password" type="password" required/></label><button className="btn btn-dark">Se connecter</button></form></section></main>}
